 const calculate=async()=>{const computed=await api('risk/calculate',{method:'POST',data:d});await edit('assessments',computed);message('Calcolo temporaneo pronto. Non ancora inserito nello storico.');};
 if(writable)bar.prepend(button('Calcola / Ricalcola',calculate,true),button('Salva e inserisci',async()=>{if(!d.result||d.status==='Modified')throw new Error('Ricalcola prima di salvare');state.request=state.request||crypto.randomUUID();const saved=await api('risk/save',{method:'POST',data:{...d,expected_version:d.version||0,request_id:state.request}});state.dirty=false;state.data.assessments=null;await edit('assessments',saved);message('Inserita nello storico · revisione '+saved.version+' · '+saved.saved_at);},true));
 if(!d.result)return;
 const r=d.result;const section=el('section',{class:'card'},el('h2',{},'Sintesi decisionale · '+state.site.name+' · '+d.month),el('p',{},`Indice base ${displayScore(r.base,r.level)} · ${r.level} · modello ${d.model_version}`),el('p',{},`Soglia ${r.floor}/100: ${r.floor_reason}`),el('p',{},'Indice contestualizzato: '+(r.context_exact===null?'non disponibile':displayScore(r.context_exact))+' · '+r.context_basis),el('p',{},'Target ispettivo comune '+d.policy.inspection_target+' · '+d.policy.version));
 const open=[...(d.events||[]),...(d.event_snapshots||[])].filter(e=>e.state==='Open');section.append(el('p',{},'Segnalazioni aperte: '+['High','Medium','Low'].map(s=>s+' '+open.filter(e=>e.severity===s).length).join(' · ')));
 for(const text of r.missing)section.append(el('p',{class:'notice'},text));
 const alerts=el('section',{class:'card'},el('h3',{},'Priorità e fonti delle segnalazioni'));for(const e of open){const item=el('article',{},el('h4',{},`${e.channel==='formal'?'NC formale':'Criticità informale'} · ${e.topic} · ${e.severity}`),el('p',{},e.description||e.reason||'Dettaglio da integrare'),el('p',{},'Proposta: verificare la condizione e definire correzione, responsabile e scadenza; non è una root cause accertata.'));if(e.id&&d.event_ids?.includes(e.id))item.append(button('Apri evento sorgente',()=>edit('events',e)));else item.append(button('Rivedi dato sorgente',()=>{state.showAssessmentStep?.(1);main.querySelector('[data-field="topic"]')?.focus();}));if(writable&&d.status==='Saved')item.append(button('Prepara azione collegata',()=>edit('actions',{site_id:d.site_id,source_type:'assessments',source_id:d.id,description:'Verificare e gestire: '+(e.description||e.topic),priority:e.severity==='High'?'Alta':'Media',status:'Open'})));alerts.append(item);}section.append(alerts);
 const drivers=el('section',{class:'card'},el('h3',{},'Contributi effettivi · punti indice'));
 for(const row of [...r.drivers.slice(0,6)].sort((a,b)=>b.Contributo-a.Contributo))drivers.append(el('div',{},el('label',{},`${row.Area}: ${row.Contributo.toFixed(3)} punti (area ${row['Indice area'].toFixed(1)}/100)`,el('meter',{min:0,max:row['Peso massimo'],value:row.Contributo,'aria-label':row.Area}))));
 const reconciliation=el('details',{},el('summary',{},'Riconciliazione: componenti, bonus, limiti e soglia'));let running=0;const steps=r.drivers.map(x=>running+=x.Contributo),lo=Math.min(0,...steps),hi=Math.max(100,...steps),span=hi-lo;running=0;for(const row of r.drivers){const before=running;running+=row.Contributo;reconciliation.append(el('div',{'aria-hidden':'true',style:`height:12px;margin-left:${(Math.min(before,running)-lo)/span*100}%;width:${Math.abs(row.Contributo)/span*100}%;background:${row.Contributo<0?'#16826B':'#A63D00'}`}),el('p',{},`${row.Area}: ${row.Contributo>=0?'+':''}${row.Contributo.toFixed(6)} → ${running.toFixed(6)}`));}drivers.append(reconciliation);
