 section.append(drivers,method);main.append(section);
 if(writable){const scenarios=el('details',{},el('summary',{},'Scenari indipendenti · nessuna modifica al salvataggio'));for(const row of d.scenarios||[])scenarios.append(el('p',{},`${row['Scenario indipendente']}: ${row['Indice simulato']} /100 · beneficio teorico ${row['Riduzione punti']} punti · soglia residua ${row['Soglia residua']}. Non sommabile agli altri scenari.`));scenarios.append(button('Copertura HSE al 100%',async()=>{if(d.status==='Modified')throw new Error('Ricalcola prima degli scenari');const sample=structuredClone(d);sample.coverage=100;const result=await api('risk/scenario',{method:'POST',data:sample});scenarios.append(el('p',{},`Copertura HSE al 100%: ${displayScore(result.result.base,result.result.level)} · beneficio teorico ${(r.base-result.result.base).toFixed(2)} punti. Non modifica il salvataggio.`));}));section.append(scenarios);}
 for(const format of ['pdf','docx','xlsx','pptx','management-pdf','json'])bar.append(button('Scarica '+format.toUpperCase(),async()=>{if(d.status==='Modified'||state.dirty)throw new Error('Ricalcola prima di esportare');const snapshot=d.status==='Saved'?await api('exports',{method:'POST',data:{site_id:d.site_id,source_id:d.id,source_version:d.version,format,request_id:crypto.randomUUID()}}):await api('risk/export',{method:'POST',data:{...d,format,request_id:crypto.randomUUID()}});await exportRecord(format,snapshot.record,snapshot.site_snapshot,{history:snapshot.history||[],actions:snapshot.actions||[],calendar:snapshot.calendar||[]});}));
